+/*
+ * @test
+ * @summary AOTClassLocationConfig::dumptime_get_class_location_index() should return the correct index
+ *          even if non-canonical paths are used in -classpath
+ * @bug 8396093
+ * @requires vm.cds.supports.aot.class.linking
+ * @library /test/lib
+ * @build CanonicalPath
+ * @run driver jdk.test.lib.helpers.ClassFileInstaller -jar app.jar CanonicalPathApp
+ * @run driver CanonicalPath
+ */
+
+import java.io.File;
+import jdk.test.lib.cds.SimpleCDSAppTester;
+import jdk.test.lib.Platform;
+import jdk.test.lib.process.OutputAnalyzer;
+
+public class CanonicalPath {
+    public static void main(String... args) throws Exception {
+        SimpleCDSAppTester.of("CanonicalPath")
+            .addVmArgs("-Xlog:aot+class=debug")
+            .classpath(nonCanonicalPath("app.jar"))
+            .appCommandLine("CanonicalPathApp")
+            .setTrainingChecker((OutputAnalyzer output) -> {
+                // CanonicalPathApp should be archived, even if its classpath
+                // location uses a non-canonical file name.
+                output.shouldMatch("aot,class.* app * CanonicalPathApp");
+            })
+            .runAOTWorkflow();
+    }
+
+
+    static String nonCanonicalPath(String fileName) throws Exception {
+        fileName = new File(fileName).getAbsolutePath();
+        if (Platform.isWindows()) {
+            // Use UNC file name
+            return "\\\\?\\" + fileName;
+        } else {
+            return TestCommon.createSymLink(fileName).getPath();
+        }
+    }
+}
+
+class CanonicalPathApp {
+    public static void main(String[] args) {
+        System.out.println("HelloWorld");
+    }
+}
